  --accent-hover: #6d5de6;
  --accent-dot:   #a78bfa;
  --success-bg:   #0f2e1f;
  --success-text: #4ade80;
  --success-border: #166534;
  --error-bg:     #2d0f0f;
  --radius-card:  16px;
  --radius-input: 8px;
  --transition:   0.15s ease;
}

/* ── Skip link ───────────────────────────────────────── */
.skip-link {
  position: absolute;
  top: -100%;
  left: 1rem;
  z-index: 999;
  padding: 0.5rem 1rem;
  background: var(--accent);
  color: #fff;
  font-weight: 600;
  border-radius: 0 0 var(--radius-input) var(--radius-input);
  text-decoration: none;
  font-size: 0.875rem;
  transition: top var(--transition);
}
.skip-link:focus { top: 0; }

/* ── Page ────────────────────────────────────────────── */
html { font-size: 16px; }

body {
  background: var(--bg-page);
  color: var(--text-primary);
  font-family: system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  line-height: 1.6;
  min-height: 100vh;
  display: flex;
  flex-direction: column;
}

/* ── Main layout ─────────────────────────────────────── */
.main {
  flex: 1;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 2rem 1rem;
}

.form-container {
  width: 100%;
  max-width: 520px;
}

/* ── Page heading ────────────────────────────────────── */
.form-title {
  font-size: 1.75rem;
  font-weight: 700;
  color: #fff;
  letter-spacing: -0.02em;
  margin-bottom: 1.5rem;
  text-align: center;
}

/* ── Status message (success / live region) ─────────── */
.status-message {
  display: none;
  padding: 0.875rem 1rem;
  border-radius: var(--radius-input);
  background: var(--success-bg);
  color: var(--success-text);
  border: 1px solid var(--success-border);
  font-size: 0.9375rem;
  margin-bottom: 1.25rem;
}
.status-message--visible { display: block; }

/* ── Form card ───────────────────────────────────────── */
.form {
  background: var(--bg-card);
  border: 1px solid var(--border);
  border-radius: var(--radius-card);
  padding: 2rem;
}

/* ── form-field wrapper ──────────────────────────────── */
.form-field { margin-bottom: 0.5rem; }

/* ── Fieldset & legend ───────────────────────────────── */
.fieldset {
  border: 1px solid var(--border);
  border-radius: var(--radius-input);
  padding: 1.25rem 1.25rem 1rem;
  background: var(--bg-card-alt);
  transition: border-color var(--transition);
}
.fieldset--error { border-color: var(--border-error); }

.legend {
  font-size: 1rem;
  font-weight: 600;
  color: #fff;
  padding: 0 0.375rem;
  line-height: 1.4;
}

.required-marker { color: #f87171; }

/* ── Error text ──────────────────────────────────────── */
.error-text {
  display: flex;
  align-items: center;
  gap: 0.375rem;
  margin-top: 0.75rem;
  padding: 0.625rem 0.875rem;
  border-radius: var(--radius-input);
  background: var(--error-bg);
  color: var(--text-error);
  font-size: 0.875rem;
  border: 1px solid #7f1d1d;
}

/* ── Radio options ───────────────────────────────────── */
.radio-options { margin-top: 1rem; display: flex; flex-direction: column; gap: 0.625rem; }

.radio-option {
  display: flex;
  align-items: center;
  gap: 0.75rem;
  padding: 0.75rem 1rem;
  border-radius: var(--radius-input);
  border: 1px solid var(--border);
  background: var(--bg-card);
  cursor: pointer;
  transition: border-color var(--transition), background var(--transition);
}
.radio-option:hover { border-color: var(--accent); background: #1c1c33; }
.radio-option:has(input:checked) {
  border-color: var(--accent);
  background: #1c1c33;
}

/* ── Custom radio input ──────────────────────────────── */
input[type="radio"] {
  appearance: none;
  -webkit-appearance: none;
  width: 1.125rem;
  height: 1.125rem;
  border: 2px solid #4a4a6a;
  border-radius: 50%;
  background: var(--bg-page);
  cursor: pointer;
  flex-shrink: 0;
  transition: border-color var(--transition);
  position: relative;
}

input[type="radio"]:checked {
  border-color: var(--accent);
  background: radial-gradient(circle, var(--accent-dot) 38%, transparent 40%);
}

input[type="radio"]:focus-visible {
  outline: 2px solid var(--border-focus);
  outline-offset: 3px;
}

/* ── Radio label ─────────────────────────────────────── */
.radio-label {
  font-size: 0.9375rem;
  color: var(--text-primary);
  cursor: pointer;
  user-select: none;
  flex: 1;
}

/* ── Required note ───────────────────────────────────── */
.required-note {
  font-size: 0.8125rem;
  color: var(--text-muted);
  margin-top: 0.875rem;
}
.required-note span { color: #f87171; }

/* ── Submit button ───────────────────────────────────── */
.submit-btn {
  display: block;
  width: 100%;
  margin-top: 1.5rem;
  padding: 0.8125rem 1.5rem;
  background: var(--accent);
  color: #fff;
  font-size: 1rem;
  font-weight: 600;
  border: none;
  border-radius: var(--radius-input);
  cursor: pointer;
  transition: background var(--transition), transform 0.1s;
  letter-spacing: 0.01em;
}
.submit-btn:hover { background: var(--accent-hover); }
.submit-btn:active { transform: scale(0.99); }
.submit-btn:focus-visible {
  outline: 2px solid var(--border-focus);
  outline-offset: 3px;
}

/* ── Reflow: narrow viewports (320 px) ───────────────── */
@media (max-width: 400px) {
  .form { padding: 1.25rem 1rem; }
  .form-title { font-size: 1.375rem; }
}

/* ── Forced-colors / high-contrast mode ─────────────── */
@media (forced-colors: active) {
  .fieldset { border: 2px solid ButtonText; }
  .radio-option { border: 1px solid ButtonText; }
  .submit-btn { forced-color-adjust: none; background: Highlight; color: HighlightText; }
}

/* ── Reduced motion ──────────────────────────────────── */
@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after { transition: none !important; }
}
