.required-note {
  font-size: 0.8125rem;
  color: var(--text-muted);
  margin-top: 0.875rem;
}
.required-note span { color: #f87171; }

/* ── Submit button ───────────────────────────────────── */
.submit-btn {
  display: block;
  width: 100%;
  margin-top: 1.5rem;
  padding: 0.8125rem 1.5rem;
  background: var(--accent);
  color: #fff;
  font-size: 1rem;
  font-weight: 600;
  border: none;
