const fs = require('fs');
const path = require('path');

(async () => {
  const html = fs.readFileSync('index.html', 'utf8');
  // Inline scripts so we don't need a server
  // Build self-contained HTML with everything inlined
  const cssPath = path.resolve('styles.css');
  const css = fs.readFileSync(cssPath, 'utf8');

  // Fetch React + ReactDOM + Babel via CDN is tricky offline — use local copies
