      await route.fulfill({ body, contentType: ct });
    } else {
      await route.continue();
    }
  });

  await page.goto('http://localhost/index.html', { waitUntil: 'networkidle' });
  // Wait for React to mount
  await page.waitForSelector('.form-container', { timeout: 10000 });

  await page.addScriptTag({ path: '/tmp/axe.min.js' });
  const results = await page.evaluate(async () => await window.axe.run());
  await browser.close();

  const wcag = results.violations.filter(v => !v.tags.includes('best-practice'));
